function start() {
  const cv = document.getElementById("qc-mol");
  if (!cv || cv.dataset.on) return;
  cv.dataset.on = "1";
  const ctx = cv.getContext("2d");
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  // 結合を点線の点に、原子を小さな点の集まりにする
  const P = [];
  const rnd = (() => { let s = 7; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();
  const gauss = () => { let u = 0, v = 0; while (!u) u = rnd(); v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  D.bonds.forEach(([i, j]) => {
    const a = D.atoms[i], b = D.atoms[j];
    for (let t = 0; t <= 1; t += 0.07) P.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, 1]);
  });
  D.atoms.forEach((a) => {
    const n = a[3] ? 26 : 10, r = a[3] ? 0.22 : 0.14;
    for (let k = 0; k < n; k++) P.push([a[0] + gauss() * r, a[1] + gauss() * r, a[2] + gauss() * r, a[3] ? 1 : 0]);
  });
  D.orb.forEach((q) => P.push(q));
  const COL = {
    light: ["rgba(120,135,150,0.55)", "rgba(70,90,110,0.75)", "rgba(42,120,214,0.38)", "rgba(176,69,154,0.38)"],
    dark: ["rgba(170,185,205,0.45)", "rgba(200,215,235,0.7)", "rgba(80,170,255,0.45)", "rgba(230,110,200,0.45)"],
  };
  let W = 0, H = 0, dpr = 1, mx = 0, my = 0;
  function resize() {
    const r = cv.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = r.width; H = r.height;
    cv.width = W * dpr; cv.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  cv.parentElement.addEventListener("pointermove", (e) => {
    const r = cv.getBoundingClientRect();
    mx = (e.clientX - r.left) / r.width - 0.5; my = (e.clientY - r.top) / r.height - 0.5;
  });
  resize();
  const t0 = performance.now();
  function frame(now) {
    const dark = document.body.getAttribute("data-md-color-scheme") === "slate";
    const col = dark ? COL.dark : COL.light;
    const t = reduce ? 0 : (now - t0) / 1000;
    const ay = 0.35 + t * 0.12 + mx * 0.6, ax = -0.95 + my * 0.4;
    const cy = Math.cos(ay), sy = Math.sin(ay), cx = Math.cos(ax), sx = Math.sin(ax);
    const s = Math.min(W, H) / 15.5, ox = W * 0.5, oy = H * 0.5;
    ctx.clearRect(0, 0, W, H);
    const pr = [];
    for (const p of P) {
      let x = p[0] * cy + p[2] * sy, z = -p[0] * sy + p[2] * cy, y = p[1];
      const y2 = y * cx - z * sx, z2 = y * sx + z * cx;
      const f = 22 / (22 - z2);
      pr.push([ox + x * s * f, oy + y2 * s * f, z2, p[3], f]);
    }
    pr.sort((a, b) => a[2] - b[2]);
    for (const q of pr) {
      ctx.fillStyle = col[q[3]];
      const r = (q[3] >= 2 ? 1.25 : 1.1) * q[4];
      ctx.beginPath(); ctx.arc(q[0], q[1], r, 0, 6.283); ctx.fill();
    }
    if (!reduce) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start); else start();
if (window.document$) window.document$.subscribe(start);
